#define C_HEART_EMPTY   0x00402020UL
#define C_HEART_GOLD    0x00F0C030UL


//*****************************************************************************
// Hearts (rc.md 5.1): at most six icons. Up to six hearts they are red (with a
// half heart where needed); health above six turns them gold from the left.
//*****************************************************************************
static void HeartRect(int16_t x, int16_t x0, int16_t y0, int16_t x1, int16_t y1,
                      int16_t lo, int16_t hi, uint32_t c)
{
    x0 = (int16_t)(x + x0);
    x1 = (int16_t)(x + x1);
    if(x0 < lo) x0 = lo;
    if(x1 > hi) x1 = hi;
    if(x1 >= x0) Graphics_FillRect(x0, y0, x1, y1, c);
}


// Draw the heart shape, only the columns lo..hi (absolute x).
static void HeartPart(int16_t x, int16_t y, int16_t lo, int16_t hi, uint32_t c)
{
    HeartRect(x, 1, y,      5, y + 1, lo, hi, c);
    HeartRect(x, 7, y,     11, y + 1, lo, hi, c);
    HeartRect(x, 0, y + 2, 12, y + 5, lo, hi, c);
    HeartRect(x, 1, y + 6, 11, y + 6, lo, hi, c);
    HeartRect(x, 2, y + 7, 10, y + 7, lo, hi, c);
    HeartRect(x, 3, y + 8,  9, y + 8, lo, hi, c);
    HeartRect(x, 4, y + 9,  8, y + 9, lo, hi, c);
    HeartRect(x, 5, y + 10, 7, y + 10, lo, hi, c);
    HeartRect(x, 6, y + 11, 6, y + 11, lo, hi, c);
}


static void DrawHearts(void)
{
    uint16_t red  = (rc_hp > 12u) ? 12u : rc_hp;
    uint16_t gold = (rc_hp > 12u) ? (uint16_t)(rc_hp - 12u) : 0u;
    uint16_t cont = (uint16_t)((((rc_maxHp > 12u) ? 12u : rc_maxHp) + 1u) >> 1);    // icons that exist
    uint16_t i, r, g;

    Graphics_FillRect(0, 0, 111, RC_VIEW_Y0 - 1, C_BLACK);
    for(i = 0; i < HP_HUD_ICONS; i++)
    {
        int16_t x = (int16_t)(5 + i * 18), y = 6;

        if(i >= cont && rc_maxHp <= 12u) break;
        r = (red  > 2u * i) ? (uint16_t)(red  - 2u * i) : 0u;  if(r > 2u) r = 2u;
        g = (gold > 2u * i) ? (uint16_t)(gold - 2u * i) : 0u;  if(g > 2u) g = 2u;

        if(g == 2u)      HeartPart(x, y, x, (int16_t)(x + 12), C_HEART_GOLD);
        else if(g == 1u)
        {
            HeartPart(x, y, x, (int16_t)(x + 6), C_HEART_GOLD);
            HeartPart(x, y, (int16_t)(x + 7), (int16_t)(x + 12), C_RED);
        }
        else if(r == 2u) HeartPart(x, y, x, (int16_t)(x + 12), C_RED);
        else if(r == 1u)
        {
            HeartPart(x, y, x, (int16_t)(x + 6), C_RED);
            HeartPart(x, y, (int16_t)(x + 7), (int16_t)(x + 12), C_HEART_EMPTY);
        }
        else             HeartPart(x, y, x, (int16_t)(x + 12), C_HEART_EMPTY);
    }
}


void rc_DrawHudFrame(void)
{
    Graphics_FillRect(0, 0, SCREEN_W - 1, RC_VIEW_Y0 - 1, C_BLACK);
    Graphics_FillRect(0, RC_VIEW_Y1 + 1, SCREEN_W - 1, SCREEN_H - 1, C_BLACK);

    if(RC_VIEW_X0 > 0)
        Graphics_FillRect(0, RC_VIEW_Y0, RC_VIEW_X0 - 1, RC_VIEW_Y1, C_BLACK);
    if(RC_VIEW_X0 + RC_VIEW_W <= SCREEN_W - 1)
        Graphics_FillRect(RC_VIEW_X0 + RC_VIEW_W, RC_VIEW_Y0, SCREEN_W - 1, RC_VIEW_Y1, C_BLACK);
}


//*****************************************************************************
// Bottom line: a message, then whatever the stick button would do, then status.
//*****************************************************************************
static void Prompt(const char *what, const char *verb, uint32_t c)
{
    rc_DrawText(what, 110, 229, c);
    Ui_DrawIcon(UI_ICON_STICK_CLICK, 214, 229, 8);
    rc_DrawText(verb, 255, 229, c);
}


static void DrawHint(void)
{
    char    buf[32];
    int16_t n;

    Graphics_FillRect(0, 217, SCREEN_W - 1, SCREEN_H - 1, C_BLACK);

    if(rc_toastT) { rc_DrawText(rc_toast, SCREEN_W / 2, 229, C_GOLD); return; }

    switch(rc_iaKind)
    {
        case IA_DOOR:
        {
            uint16_t cost = rc_DoorCost();
            uint32_t c    = (rc_gold >= cost) ? C_GREEN : C_BAD;

            n = rc_Cat(buf, 0, "Door ", 5);
            n += rc_Itoa(buf + n, cost);
            rc_Cat(buf, n, "G", 1);
            Prompt(buf, "Buy", c);
            return;
        }
        case IA_SECRET:                             // keys are the currency of secret doors
            if(rc_keys) Prompt("Secret door 1 KEY", "Open", C_GOLD);
            else        rc_DrawText("Secret door: needs a key", SCREEN_W / 2, 229, C_BAD);
            return;
        case IA_EXIT:   Prompt("Hidden exit", "Open", C_GREEN);  return;
        case IA_CHEST:  Prompt("Chest", "Open", C_GOLD);          return;
        case IA_VENDOR: Prompt("Vendor", "Trade", C_GOLD);        return;
        case IA_SHRINE: Prompt("Shrine", "Pray", C_XP);           return;
        case IA_LAB:    Prompt("Rune altar", "Study", C_CYAN);    return;
        default: break;
    }

    if(rc_nearSecret)   rc_DrawText(rc_keys ? "This wall seems strange..." : "This wall seems strange (key?)",
                                    SCREEN_W / 2, 229, C_GOLD);
    else if(rc_silence) rc_DrawText("SPELLS DISABLED!", SCREEN_W / 2, 229, C_XP);
    else if(rc_confuse) rc_DrawText("CONFUSED!", SCREEN_W / 2, 229, C_XP);
    else if(rc_aegis)   rc_DrawText("SHIELD UP!", SCREEN_W / 2, 229, COLOR_SKY_BLUE);
    else if(rc_haste)   rc_DrawText("HASTE!", SCREEN_W / 2, 229, C_GOLD);
    else if(rc_nullify) rc_DrawText("MAGIC WEAKENED!", SCREEN_W / 2, 229, C_XP);
    else if(rc_pSlow)   rc_DrawText("SLOWED!", SCREEN_W / 2, 229, COLOR_SKY_BLUE);
    else if(rc_denState == DEN_OPEN && rc_dragonKills == 0u)
        rc_DrawText("The Dragon Den is open!", SCREEN_W / 2, 229, C_RED);
    else if(rc_playerRoom < RM_COUNT && rc_wave > 1u)
        rc_DrawText(rc_kRoom[rc_playerRoom].name, SCREEN_W / 2, 229, C_GRAY);
    else
    {
        static const UiHint k[] =
        {
            { UI_ICON_STICK, "Move" },
            { UI_ICON_D,     "Fire" },
            { UI_ICON_U,     "Swap" },
            { UI_ICON_L,     ""     },
            { UI_ICON_R,     "Turn" }
        };
        Ui_DrawHints(k, UI_ARRAY_LEN(k), 229, C_BLACK);
    }
}


// "ahead / left / right / behind" and the distance to a point (treasure pointer).
static void Direction(int32_t x, int32_t y, char *buf)
{
    int16_t dx = RD(x - rc_px), dy = RD(y - rc_py);
    int32_t fwd  = (((int32_t)dx * COS(rc_ang)) + ((int32_t)dy * SIN(rc_ang))) >> 14;
    int32_t side = (((int32_t)dy * COS(rc_ang)) - ((int32_t)dx * SIN(rc_ang))) >> 14;
    int32_t af = (fwd < 0) ? -fwd : fwd, as = (side < 0) ? -side : side;
    const char *w = (af >= as) ? ((fwd >= 0) ? "ahead " : "behind ") : ((side >= 0) ? "right " : "left ");
    int16_t n = rc_Cat(buf, 0, w, 8);

    n += rc_Itoa(buf + n, (uint16_t)(Dist10(dx, dy) >> 10));
    rc_Cat(buf, n, "m", 1);
}


void rc_DrawHud(void)
{
    char    buf[24];
    int16_t n, i;

    if(rc_hud & HUD_HEARTS) DrawHearts();

    if(rc_hud & HUD_TOPR)                    // wave, level, keys, gold, XP bar
    {
        int16_t w;

        Graphics_FillRect(112, 0, SCREEN_W - 1, RC_VIEW_Y0 - 1, C_BLACK);

        if(rc_denState == DEN_FIGHT)
            rc_DrawSmall("DRAGON", 140, 8, C_RED, C_BLACK);
        else
        {
            n = rc_Cat(buf, 0, "WAVE ", 5);
            rc_Itoa(buf + n, rc_wave);
            rc_DrawSmall(buf, 140, 8, rc_lv.dragon ? C_RED : rc_lv.treasure ? C_GOLD : C_WHITE, C_BLACK);
        }

        n = rc_Cat(buf, 0, "LV ", 3);
        rc_Itoa(buf + n, rc_xpLv);
        rc_DrawSmall(buf, 196, 8, C_XP, C_BLACK);

        n = rc_Cat(buf, 0, "KEY ", 4);
        rc_Itoa(buf + n, rc_keys);
        rc_DrawSmall(buf, 240, 8, rc_keys ? C_GOLD : C_DKGRAY, C_BLACK);

        n = rc_Cat(buf, 0, "G ", 2);
        rc_Itoa(buf + n, rc_gold);
        rc_DrawSmall(buf, 290, 8, C_GOLD, C_BLACK);

        Graphics_FillRect(XP_BAR_X0, XP_BAR_Y0, XP_BAR_X1, XP_BAR_Y1, C_DKGRAY);
        Graphics_FillRect(XP_BAR_X0 + 1, XP_BAR_Y0 + 1, XP_BAR_X1 - 1, XP_BAR_Y1 - 1, COLOR_TETRIS_GRID);
        w = (int16_t)(((int32_t)rc_xp * (XP_BAR_X1 - XP_BAR_X0 - 1)) / rc_XpNeed());
        if(w > 0)
            Graphics_FillRect(XP_BAR_X0 + 1, XP_BAR_Y0 + 1, XP_BAR_X0 + w, XP_BAR_Y1 - 1, C_XP);
    }

    if(rc_hud & HUD_STAFF)                      // the selected staff / consumable, class, ultimate meter
    {
        uint16_t it = rc_SelItem();

        Graphics_FillRect(0, RC_VIEW_Y1 + 2, 189, 215, C_BLACK);
        rc_DrawText(rc_kItems[it].name, 85, 201, (it < NUM_STAFFS) ? rc_kStaffs[it].color : C_WHITE);
        if(it < NUM_STAFFS)
        {
            n = rc_Cat(buf, 0, "MP ", 3);
            rc_Itoa(buf + n, rc_StaffMana());
            rc_DrawSmall(buf, 172, 202, C_MANA, C_BLACK);
        }
        else
        {
            n = rc_Cat(buf, 0, "x", 1);
            rc_Itoa(buf + n, rc_inv[rc_sel].cnt);
            rc_DrawSmall(buf, 172, 202, C_WHITE, C_BLACK);
        }
        rc_cdShown = -1;
    }

    if(rc_hud & HUD_ULT)                        // ultimate meter (gold when full, red while it runs)
    {
        int16_t y0 = RC_VIEW_Y0, y1 = RC_VIEW_Y1, h;

        Graphics_FillRect(ULT_X0 - 1, y0, ULT_X1 + 1, y1, C_BLACK);
        Graphics_FillRect(ULT_X0, y0, ULT_X1, y1, C_DKGRAY);
        Graphics_FillRect(ULT_X0 + 1, y0 + 1, ULT_X1 - 1, y1 - 1, COLOR_TETRIS_GRID);
        h = (int16_t)(((int32_t)(rc_ultT ? ULT_FULL : rc_ult) * (RC_VIEW_H - 2)) / ULT_FULL);
        if(rc_class && h > 0)
            Graphics_FillRect(ULT_X0 + 1, y1 - h, ULT_X1 - 1, y1 - 1,
                              rc_ultT ? C_RED : (rc_ult >= ULT_FULL) ? C_GOLD : C_XP);
    }

    if(rc_hud & HUD_LEFT)                    // boss bar / next wave / treasure pointer / enemies left
    {
        const Enemy *boss = NULL;

        Graphics_FillRect(190, RC_VIEW_Y1 + 2, SCREEN_W - 1, 215, C_BLACK);
        for(i = 0; i < RC_MAX_ENEMIES; i++)
        {
            const Enemy *e = &rc_en[i];
            if(!e->alive || !RC_IS_BOSS(e->type)) continue;
            if(boss == NULL || e->type == ET_DRAGON) boss = e;
        }

        if(boss != NULL)
        {
            int16_t w = (int16_t)(((int32_t)boss->hp * 124L) / (boss->mhp ? boss->mhp : 1));

            rc_DrawSmall(rc_kEnemyName[boss->type], 254, 199, C_RED, C_BLACK);
            Graphics_FillRect(192, 208, 317, 213, C_DKGRAY);
            if(w > 0) Graphics_FillRect(193, 209, (int16_t)(193 + w - 1), 212, C_RED);
        }
        else if(rc_roundGap && rc_denState == DEN_OPEN && rc_dragonKills == 0u)
            rc_DrawText("Enter the Den", 255, 203, C_RED);      // waves wait for the player
        else if(rc_roundGap)
        {
            n = rc_Cat(buf, 0, "Next wave ", 10);
            rc_Itoa(buf + n, (uint16_t)((rc_roundGap + 29u) / 30u));
            rc_DrawText(buf, 255, 203, C_GREEN);
        }
        else if(rc_treasureOpen == 1u && rc_treasureProp >= 0)
        {
            rc_DrawSmall("TREASURE", 254, 199, C_GOLD, C_BLACK);
            Direction(rc_prop[rc_treasureProp].x, rc_prop[rc_treasureProp].y, buf);
            rc_DrawSmall(buf, 254, 210, C_WHITE, C_BLACK);
        }
        else
        {
            n = rc_Cat(buf, 0, "Left ", 5);
            rc_Itoa(buf + n, (uint16_t)(rc_toSpawn + rc_CountRegular() + (rc_miniPending ? 1u : 0u)));
            rc_DrawText(buf, 255, 203, C_WHITE);
        }
    }

    if(rc_hud & HUD_HINT) DrawHint();

    rc_hud = 0;
}


void rc_DrawCdStrip(void)
{
    uint16_t it = rc_SelItem();
    uint16_t cd = (it < NUM_STAFFS) ? rc_cdStaff : rc_cdCons[it - I_FIRST_CONS];
    uint16_t mx = (it < NUM_STAFFS) ? rc_cdStaffMax : (uint16_t)(rc_kItems[it].val * 10u);
    int16_t  w;

    if(cd == 0 || mx == 0) w = CD_STRIP_W;
    else
    {
        w = (int16_t)(CD_STRIP_W - (int16_t)(((int32_t)cd * CD_STRIP_W) / mx));
        if(w < 0) w = 0;
    }

    if(w == rc_cdShown) return;

    if(rc_cdShown >= 0 && w > rc_cdShown && w < CD_STRIP_W)
        Graphics_FillRect(CD_STRIP_X0 + rc_cdShown, 213, CD_STRIP_X0 + w - 1, 215, C_GRAY);
    else
    {
        Graphics_FillRect(CD_STRIP_X0, 213, CD_STRIP_X0 + CD_STRIP_W - 1, 215, C_DKGRAY);
        if(w > 0)
            Graphics_FillRect(CD_STRIP_X0, 213, CD_STRIP_X0 + w - 1, 215,
                              (w == CD_STRIP_W) ? C_CYAN : C_GRAY);
    }
    rc_cdShown = w;
}


void rc_DrawManaBar(void)
{
    int16_t  y0 = RC_VIEW_Y0, y1 = RC_VIEW_Y1;
    int16_t  inB = (int16_t)(y1 - 1);
    int16_t  inH = (int16_t)(RC_VIEW_H - 2);
    int16_t  h   = (int16_t)(((int32_t)rc_mana * inH) / rc_ManaMax());
    bool     fl  = (rc_manaFlash != 0);
    uint32_t col = fl ? C_RED : C_MANA;

    if(rc_manaFlash) rc_manaFlash--;
    if(h > inH) h = inH;

    if(h == rc_manaShown && fl == rc_manaFlashShown) return;

    if(rc_manaShown < 0 || fl != rc_manaFlashShown)
    {
        Graphics_FillRect(0, y0, MANA_X1 + 1, y1, C_BLACK);
        Graphics_FillRect(MANA_X0, y0, MANA_X1, y1, C_DKGRAY);
        Graphics_FillRect(MANA_X0 + 1, y0 + 1, MANA_X1 - 1, y1 - 1, COLOR_TETRIS_GRID);
        if(h > 0)
            Graphics_FillRect(MANA_X0 + 1, inB - h + 1, MANA_X1 - 1, inB, col);
    }
    else if(h > rc_manaShown)
        Graphics_FillRect(MANA_X0 + 1, inB - h + 1, MANA_X1 - 1, inB - rc_manaShown, col);
    else
        Graphics_FillRect(MANA_X0 + 1, inB - rc_manaShown + 1, MANA_X1 - 1, inB - h, COLOR_TETRIS_GRID);

    rc_manaShown      = h;
    rc_manaFlashShown = fl;
}
